    // Initialize a boolean array
    boolean[] booleanArray = {true, false, true, false, true};

    // Print the original boolean array
    System.out.println("Original boolean array: " + Arrays.toString(booleanArray));

    // Remove the element at index 2
    booleanArray = ArrayUtils.remove(booleanArray, 2);

    // Print the modified boolean array
    System.out.println("Modified boolean array: " + Arrays.toString(booleanArray));
